def simpan_nama(daftar, nama_berkas):
    with open(nama_berkas, "____") as f:
        for nama in daftar:
            f.write(nama + "\n")


def baca_nama(nama_berkas):
    hasil = []
    with open(nama_berkas) as f:
        for baris in f:
            hasil.append(baris.____())
    return hasil
